mapper.select:

SELECT COUNT(*)
FROM tb_purchase_order
WHERE request_id=#{id}

mapper.update:

UPDATE tb_compensation
SET state=#{outcome}, attempts=#{attempts}, next_at_ms=#{next}, updated_at_ms=#{now}
WHERE request_id=#{id}

mapper.select:

SELECT request_id
FROM tb_compensation
WHERE state='PENDING'
AND next_at_ms<=#{now}
ORDER BY next_at_ms
LIMIT #{limit}
